  final resp =
      SyncHttpClient.get('${_prUrl(c, a)}/reviews', headers: c.headers);
  final body = syncBodyOrError(resp);
  if (!resp.isOk) return body;
  return body.trim().isEmpty ? '[]' : body;
}

